838  hb_ot_shape_internal (hb_ot_shape_context_t *c)
   839  {
   840    c->buffer->deallocate_var_all ();
   841    c->buffer->scratch_flags = HB_BUFFER_SCRATCH_FLAG_DEFAULT;
   842    if (likely (!hb_unsigned_mul_overflows (c->buffer->len, HB_BUFFER_MAX_LEN_FACTOR)))
   843    {
   844      c->buffer->max_len = MAX (c->buffer->len * HB_BUFFER_MAX_LEN_FACTOR,
   845                                (unsigned) HB_BUFFER_MAX_LEN_MIN);
   846    }
   847    if (likely (!hb_unsigned_mul_overflows (c->buffer->len, HB_BUFFER_MAX_OPS_FACTOR)))
   848    {
   849      c->buffer->max_ops = MAX (c->buffer->len * HB_BUFFER_MAX_OPS_FACTOR,
   850                                (unsigned) HB_BUFFER_MAX_OPS_MIN);
   851    }
   852
   853    bool disable_otl = c->plan->shaper->disable_otl && c->plan->shaper->disable_otl (c->plan);
   854    //c->fallback_substitute     = disable_otl || !hb_ot_layout_has_substitution (c->face);
   855    c->fallback_positioning    = disable_otl || !hb_ot_layout_has_positioning (c->face);
   856    c->fallback_glyph_classes  = disable_otl || !hb_ot_layout_has_glyph_classes (c->face);
   857
   858    /* Save the original direction, we use it later. */
   859    c->target_direction = c->buffer->props.direction;
   860
   861    _hb_buffer_allocate_unicode_vars (c->buffer);
   862
   863    c->buffer->clear_output ();
   864
   865    hb_ot_shape_initialize_masks (c);
   866    hb_set_unicode_props (c->buffer);
   867    hb_insert_dotted_circle (c->buffer, c->font);
   868
   869    hb_form_clusters (c->buffer);
   870
   871    hb_ensure_native_direction (c->buffer);
   872
   873    if (c->plan->shaper->preprocess_text)
   874      c->plan->shaper->preprocess_text (c->plan, c->buffer, c->font);
   875
   876    hb_ot_substitute (c);
   877    hb_ot_position (c);
   878
   879    hb_ot_hide_default_ignorables (c);
   880
   881    if (c->plan->shaper->postprocess_glyphs)
   882      c->plan->shaper->postprocess_glyphs (c->plan, c->buffer, c->font);
   883
   884    hb_propagate_flags (c->buffer);
   885
   886    _hb_buffer_deallocate_unicode_vars (c->buffer);
   887
   888    c->buffer->props.direction = c->target_direction;
   889
   890    c->buffer->max_len = HB_BUFFER_MAX_LEN_DEFAULT;
   891    c->buffer->max_ops = HB_BUFFER_MAX_OPS_DEFAULT;
   892    c->buffer->deallocate_var_all ();
   893  }
